// Production FileSidebar and OfficePreview, using JSON generated by real Go parsers.
import assert from "node:assert/strict";
import fs from "node:fs/promises";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
assert.ok(process.env.TMPDIR?.startsWith(path.join(root, "build/tmp/")));
const require = createRequire(path.join(root, "web/package.json"));
const { createServer } = await import(require.resolve("vite"));
const { default: react } = await import(require.resolve("@vitejs/plugin-react"));
const { chromium } = createRequire(path.join(process.env.SPOOL_NODE_MODULES || path.join(root, "web/node_modules"), "__office__.cjs"))("playwright");
const fixture = JSON.parse(await fs.readFile(path.join(root, "android/app/src/test/resources/office-preview.json"), "utf8"));
const output = path.join(root, "build/artifacts/office-preview"); await fs.mkdir(output, { recursive: true });
const requests = [], errors = [];
const script = `import React,{useState} from 'react';import {createRoot} from 'react-dom/client';import {flushSync} from 'react-dom';
import {FileSidebar} from '/src/file-sidebar.tsx';import {translator} from '/src/i18n.ts';import '/src/style.css';const t=translator('zh-CN');
function Scene(){const [selection,setSelection]=useState({target:{path:'report.docx'},scope:'test',request:1});window.openFile=path=>flushSync(()=>setSelection(old=>({target:{path},scope:'test',request:old.request+1})));
return <div className="app left-collapsed" style={{'--right-panel-width':'460px'}}><main className="workspace"/><FileSidebar project={{id:'project',name:'Office preview'}} chatID="chat" workspace={{path:'/work',kind:'main',available:true}} onRefreshWorkspace={()=>{}} active={true} mobileOpen={true} width={460} selection={selection} t={t} theme="light" onOpen={target=>window.openFile(target.path)} onClose={()=>{}} onResize={()=>{}} onClear={()=>{}}/></div>};createRoot(document.getElementById('root')).render(<Scene/>);`;
const plugin = {
  name: "office-preview-smoke", resolveId: id => id === "/__office.tsx" ? id : undefined, load: id => id === "/__office.tsx" ? script : undefined,
  configureServer(server) {
    server.middlewares.use(async (req,res,next) => {
      if (req.url === "/__office") { res.setHeader("Content-Type", "text/html"); res.end(await server.transformIndexHtml(req.url, '<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><div id="root"></div><script type="module" src="/__office.tsx"></script>')); return; }
      if (!req.url.startsWith("/api/")) return next();
      const url = new URL(req.url,"http://localhost"), file = url.searchParams.get("path"); requests.push(url.pathname+url.search);
      res.setHeader("Content-Type","application/json");
      if (url.pathname.endsWith("/files")) { res.end(JSON.stringify({path:".",entries:[{path:"report.docx",name:"report.docx",kind:"file"},{path:"book.xlsx",name:"book.xlsx",kind:"file"}]})); return; }
      if (url.searchParams.has("office")) {
        if (file === "broken.docx") { res.statusCode=400;res.end(JSON.stringify({error:"Malformed document"}));return; }
        if (file === "slow.docx") await new Promise(resolve=>setTimeout(resolve,400));
        const sheet=Number(url.searchParams.get("sheet")), row=Number(url.searchParams.get("row"));
        res.end(JSON.stringify(file?.endsWith(".xlsx") ? fixture.sheets[sheet===1?2:sheet===2?3:row===0?0:1] : fixture.word));return;
      }
      res.end(JSON.stringify({path:file,name:file,kind:"binary",media_type:"application/zip",size:1024,content:null,truncated:false}));
    });
  },
};
let server,browser;
try {
  server=await createServer({root:path.join(root,"web"),configFile:false,plugins:[react(),plugin],server:{host:"127.0.0.1",port:0}});await server.listen();
  browser=await chromium.launch({channel:"chrome",headless:true});const page=await browser.newPage({viewport:{width:1280,height:900}});
  page.on("pageerror",error=>errors.push(String(error)));
  await page.goto(`http://127.0.0.1:${server.httpServer.address().port}/__office`);
  await page.getByRole("heading",{name:"Office 预览"}).waitFor();
  const image=page.locator(".office-document img");await image.waitFor();assert.ok(await image.evaluate(img=>img.complete && img.naturalWidth===64));
  assert.equal(await page.locator(".office-document script").count(),0);assert.equal(await page.locator('.office-document td[colspan="2"]').textContent(),"合并标题");
  await page.screenshot({path:path.join(output,"word-desktop.png")});
  await page.evaluate(()=>window.openFile("book.xlsx"));await page.getByRole("button",{name:"工作表",exact:true}).waitFor();await page.locator(".office-sheet").waitFor();
  assert.ok(await page.getByText("$2.50",{exact:true}).count()>0);
  await page.getByRole("button",{name:"下一组行",exact:true}).click();await page.getByText("第 51–100 行",{exact:true}).waitFor();
  assert.equal(await page.locator('.office-sheet td[rowspan="2"]').textContent(),"49");
  await page.getByRole("button",{name:"工作表",exact:true}).click();await page.getByRole("option",{name:"Summary",exact:true}).click();await page.getByText("Summary worksheet",{exact:true}).waitFor();
  await page.getByRole("button",{name:"工作表",exact:true}).click();await page.getByRole("option",{name:"Empty",exact:true}).click();await page.getByText("此工作表为空。",{exact:true}).waitFor();
  await page.evaluate(()=>window.openFile("book.xlsx"));await page.getByText("第 1–50 行",{exact:true}).waitFor();
  await page.setViewportSize({width:390,height:844});
  await page.evaluate(async()=>{await Promise.all(document.getAnimations().map(a=>a.finished.catch(()=>{})));});
  assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));
  assert.ok(await page.locator(".office-scroll").evaluate(element=>element.scrollWidth>element.clientWidth));
  await page.screenshot({path:path.join(output,"excel-mobile.png")});
  await page.evaluate(()=>window.openFile("broken.docx"));await page.getByRole("alert").waitFor();assert.equal(await page.locator(".office-sheet").count(),0);
  await page.evaluate(()=>window.openFile("slow.docx"));await page.getByRole("status").waitFor();await page.evaluate(()=>window.openFile("book.xlsx"));await page.locator(".office-sheet").waitFor();
  await page.waitForTimeout(450);assert.equal(await page.locator(".office-document").count(),0);
  await page.evaluate(()=>window.openFile("report.docx"));await page.getByRole("heading",{name:"Office 预览"}).waitFor();
  await page.screenshot({path:path.join(output,"word-mobile.png")});
  assert.ok(requests.every(value=>value.startsWith("/api/chats/chat/")));assert.deepEqual(errors,[]);
  const report={wordTextImagesTables:true,worksheetSelection:true,formattedValues:true,pagedMergedCells:true,mobileHorizontalScrolling:true,errorFallback:true,staleResponseDiscarded:true,chatAuthorizationPaths:true,javascriptErrors:errors};
  await fs.writeFile(path.join(output,"browser-report.json"),JSON.stringify(report,null,2)+"\n");console.log(report);
} finally {if(browser)await browser.close();if(server)await server.close();}
